// Helper functions for Admin Appointments Status Filter
const getUniqueStatuses = () => {
  const statuses = new Set();
  const isAmbherUser = isAmbherOnlyUser();
  const isBautistaUser = isBautistaOnlyUser();
  const isAdmin = currentuserloggedin === "Admin";
  
  patientappointments.forEach(appointment => {
    // Add Ambher statuses if user has access to Ambher clinic
    if ((isAmbherUser || isAdmin) && appointment.patientambherappointmentstatus) {
      statuses.add(appointment.patientambherappointmentstatus);
    }
    // Add Bautista statuses if user has access to Bautista clinic
    if ((isBautistaUser || isAdmin) && appointment.patientbautistaappointmentstatus) {
      statuses.add(appointment.patientbautistaappointmentstatus);
    }
  });
  return Array.from(statuses).sort();
};

const getStatusCount = (status) => {
  // Count total appointment slots with this status based on user's clinic access
  let count = 0;
  const isAmbherUser = isAmbherOnlyUser();
  const isBautistaUser = isBautistaOnlyUser();
  const isAdmin = currentuserloggedin === "Admin";
  
  patientappointments.forEach(appointment => {
    // Count Ambher appointments if user has access to Ambher clinic
    if ((isAmbherUser || isAdmin) && appointment.patientambherappointmentstatus === status) {
      count++;
    }
    // Count Bautista appointments if user has access to Bautista clinic
    if ((isBautistaUser || isAdmin) && appointment.patientbautistaappointmentstatus === status) {
      count++;
    }
  });
  return count;
};

const toggleStatusFilter = (status) => {
  setStatusFilter(prev => {
    if (prev.includes(status)) {
      return prev.filter(s => s !== status);
    } else {
      return [...prev, status];
    }
  });
};

const toggleColumn = (columnKey) => {
  setVisibleColumns(prev => ({
    ...prev,
    [columnKey]: !prev[columnKey]
  }));
};

const getSortedAndFilteredAppointments = () => {
  let appointments = searchAppointments.trim() ? filteredAppointments : patientappointments;
  
  // Apply status filter
  if (statusFilter.length > 0) {
    appointments = appointments.filter(appointment => 
      statusFilter.includes(appointment.patientambherappointmentstatus) ||
      statusFilter.includes(appointment.patientbautistaappointmentstatus)
    );
  }
  
  // Sort appointments by upcoming dates
  appointments = [...appointments].sort((a, b) => {
    const now = new Date();
    now.setHours(0, 0, 0, 0); // Reset to start of day for accurate comparison
    
    // Helper function to get the nearest upcoming appointment date
    const getNearestDate = (appointment) => {
      const dates = [];
      
      // Add Ambher appointment date if exists and not cancelled/declined/expired
      if (appointment.patientambherappointmentdate && 
          !['Cancelled', 'Declined', 'Expired', 'Completed'].includes(appointment.patientambherappointmentstatus)) {
        dates.push(new Date(appointment.patientambherappointmentdate));
      }
      
      // Add Bautista appointment date if exists and not cancelled/declined/expired
      if (appointment.patientbautistaappointmentdate && 
          !['Cancelled', 'Declined', 'Expired', 'Completed'].includes(appointment.patientbautistaappointmentstatus)) {
        dates.push(new Date(appointment.patientbautistaappointmentdate));
      }
      
      // Filter out past dates and find the nearest upcoming date
      const futureDates = dates.filter(date => date >= now);
      
      if (futureDates.length > 0) {
        // Return the nearest upcoming date
        return new Date(Math.min(...futureDates));
      }
      
      // If no future dates, return the most recent past date or created date
      if (dates.length > 0) {
        return new Date(Math.max(...dates));
      }
      
      // Fallback to created date
      return new Date(appointment.createdAt);
    };
    
    const dateA = getNearestDate(a);
    const dateB = getNearestDate(b);
    
    // Both are future dates - sort by nearest first
    const isAfutureDate = dateA >= now;
    const isBfutureDate = dateB >= now;
    
    if (isAfutureDate && isBfutureDate) {
      return dateA - dateB; // Nearest future date first
    }
    
    // A is future, B is past - A comes first
    if (isAfutureDate && !isBfutureDate) {
      return -1;
    }
    
    // B is future, A is past - B comes first
    if (!isAfutureDate && isBfutureDate) {
      return 1;
    }
    
    // Both are past dates - sort by most recent first
    return dateB - dateA;
  });
  
  return appointments;
};

